// AJUSTE AQUI: coloque o seu Workspace/Team ID do ClickUp.
// Encontre em app.clickup.com na URL (https://app.clickup.com/<TEAM_ID>/...)
// ou via GET https://api.clickup.com/api/v2/team.
const teamId = '9011440385';

// Seu member ID no ClickUp (ja fixado no node de HTTP como assignees[]).
const memberId = 158519491;

return [{ json: { teamId, memberId } }];

// Monta, para cada tarefa do ClickUp, o comando do TaskWarrior.
//
// - Descricao = nome da tarefa.
// - project:ClickUp e tags +clickup +work em toda tarefa.
// - UDA client = nome da List do ClickUp (list.name).
// - UDA clickup_id = id da tarefa no ClickUp (deduplicacao). Requer
//   uda.clickup_id no taskrc (home/taskwarrior).
// - O RESUMO do text_content (gerado pelo Ollama) vira uma annotation.
// - due e priority mapeados do ClickUp.
//
// O comando usa aspas simples com escape seguro (sem injecao via SSH).

function shSingleQuote(s) {
  return "'" + String(s).replace(/'/g, "'\\''") + "'";
}

// text_content vem com \n e entidades HTML (&nbsp;). Normaliza para uma
// linha so e limita o tamanho (emails longos viram annotation gigante).
function cleanText(s, max) {
  let x = String(s || '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
  if (x.length > max) x = x.slice(0, max).trimEnd() + '...';
  return x;
}

// O node do Ollama substitui os campos do item, entao a tarefa original vem
// de 'Filtrar novas' e e pareada com o resumo pela mesma POSICAO.
const tarefas = $('Filtrar novas').all();
const resumos = $input.all();

function textoDoResumo(r) {
  if (!r || !r.json || r.json.error) return '';
  const j = r.json;
  const v = (j.message && j.message.content) ?? j.text ?? j.content ?? '';
  return String(v).replace(/\s+/g, ' ').trim();
}

const out = [];
for (let idx = 0; idx < tarefas.length; idx++) {
  const t = tarefas[idx].json;
  const id = t.id || '';
  const name = (t.name || '(sem titulo)').replace(/[\r\n]+/g, ' ').trim();

  // due date: epoch em ms (string) ou null.
  let dueArg = '';
  if (t.due_date) {
    const ms = Number(t.due_date);
    if (!Number.isNaN(ms) && ms > 0) {
      const d = new Date(ms);
      const yyyy = d.getFullYear();
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      const dd = String(d.getDate()).padStart(2, '0');
      dueArg = ` due:${yyyy}-${mm}-${dd}`;
    }
  }

  // prioridade ClickUp (1 Urgent .. 4 Low) -> TaskWarrior (H/M/L)
  let prioArg = '';
  const pid = t.priority ? Number(t.priority.id) : null;
  if (pid === 1 || pid === 2) prioArg = ' priority:H';
  else if (pid === 3) prioArg = ' priority:M';
  else if (pid === 4) prioArg = ' priority:L';

  // client = nome da List do ClickUp
  const listName = t.list && t.list.name ? String(t.list.name).replace(/[\r\n]+/g, ' ').trim() : '';
  const clientArg = listName ? ` client:${shSingleQuote(listName)}` : '';

  const descArg = shSingleQuote(name);
  const idArg = id ? ` clickup_id:${shSingleQuote(id)}` : '';

  let project_name =  "ClickUp";
  if (name.startsWith("Ticket")) project_name = "Suporte";

  const addCmd = `task add ${descArg} project:${project_name} +clickup +work${clientArg}${idArg}${prioArg}${dueArg}`;

  // annotation com o text_content (se houver)
  let note = cleanText(textoDoResumo(resumos[idx]), 500);
  if (!cleanText(t.text_content, 1) || /^VAZIO\.?$/i.test(note)) note = '';
  const annotateCmd = id && note
    ? `task rc.confirmation=no rc.verbose=nothing clickup_id:${shSingleQuote(id)} annotate ${shSingleQuote(note)}`
    : '';

  // Idempotente: so cria (e anota) se ainda nao existe tarefa com o clickup_id.
  let command;
  if (id) {
    const existsFilter = `clickup_id:${shSingleQuote(id)}`;
    const createCmd = annotateCmd ? `${addCmd} && ${annotateCmd}` : addCmd;
    command = `if test "$(task rc.verbose=nothing ${existsFilter} count 2>/dev/null)" = "0"; then ${createCmd}; else echo 'ja existe: ${id}'; fi`;
  } else {
    command = addCmd;
  }

  // O shell de login do SSH na nobita e o fish, que nao entende `if ...; then`.
  // Entao o script bash vai em base64 e e executado por `bash`: sem problema
  // de sintaxe nem de aspas no fish.
  const b64 = Buffer.from(command, 'utf8').toString('base64');
  const sshCommand = `printf %s '${b64}' | base64 -d | bash`;

  out.push({ json: { clickupId: id, name, client: listName, command, sshCommand } });
}
return out;

// Mantem so as tarefas do ClickUp que ainda NAO existem no TaskWarrior,
// para o Ollama resumir apenas as novas (e nao tudo a cada hora).
const raw = ($('SSH: ids existentes').first().json.stdout || '').trim();
let existentes;
try {
  const tasks = raw ? JSON.parse(raw) : [];
  existentes = new Set(tasks.map((t) => t.clickup_id).filter(Boolean));
} catch (e) {
  throw new Error('Nao consegui ler o export do TaskWarrior: ' + raw.slice(0, 200));
}
return $input.all().filter((i) => i.json.id && !existentes.has(i.json.id));
